document.addEventListener("DOMContentLoaded", () => {
  buildQuiz();

  document.getElementById("quiz-form").addEventListener("submit", (e) => {
    e.preventDefault();
    const answers = getAnswers();
    showResults(answers);
  });

  document.getElementById("btn-retry").addEventListener("click", resetQuiz);
});

