+      { id: "q2c", text: "C" },
+      { id: "q2d", text: "Kotlin" },
+    ],
+    correct: ["q2a", "q2c"],
+  },
+  {
+    id: "q3",
+    text: "Which of the following languages support first-class functions?",
+    help: null,
+    choices: [
+      { id: "q3a", text: "JavaScript" },
+      { id: "q3b", text: "Haskell" },
+      { id: "q3c", text: "Python" },
+      { id: "q3d", text: "COBOL" },
+    ],
+    correct: ["q3a", "q3b", "q3c"],
+  },
