+
+function buildQuiz() {
+  const form = document.getElementById("quiz-form");
+
+  QUESTIONS.forEach((q, idx) => {
+    const field = document.createElement("div");
+    field.className = "form-field";
+    field.id = q.id;
+
+    const num = document.createElement("p");
+    num.className = "question-number";
+    num.textContent = `Question ${idx + 1} of ${QUESTIONS.length}`;
+
+    const title = document.createElement("p");
+    title.className = "question-text";
+    title.id = `${q.id}-label`;
+    title.textContent = q.text;
+
+    field.appendChild(num);
+    field.appendChild(title);
+
+    if (q.help) {
+      const help = document.createElement("p");
+      help.className = "help-text";
+      help.id = `${q.id}-help`;
+      help.textContent = q.help;
+      field.appendChild(help);
+    }
+
+    const list = document.createElement("ul");
+    list.className = "choices";
+    list.setAttribute("role", "group");
+    list.setAttribute("aria-labelledby", `${q.id}-label`);
+    if (q.help) list.setAttribute("aria-describedby", `${q.id}-help`);
+
+    q.choices.forEach((choice) => {
+      const li = document.createElement("li");
+
+      const label = document.createElement("label");
+      label.className = "choice-label";
+      label.htmlFor = choice.id;
+
+      const cb = document.createElement("input");
+      cb.type = "checkbox";
+      cb.id = choice.id;
+      cb.name = q.id;
+      cb.value = choice.id;
+
+      const span = document.createElement("span");
+      span.className = "choice-text";
+      span.textContent = choice.text;
+
+      label.appendChild(cb);
+      label.appendChild(span);
+      li.appendChild(label);
+      list.appendChild(li);
+    });
+
+    field.appendChild(list);
+    form.insertBefore(field, document.getElementById("submit-row"));
+  });
+}
