+    const checked = [...document.querySelectorAll(`input[name="${q.id}"]:checked`)].map(
+      (el) => el.value
+    );
+    return { q, checked };
+  });
+}
+
+function arraysMatch(a, b) {
+  return a.length === b.length && [...a].sort().join() === [...b].sort().join();
+}
