+      : "Nice try! Review your answers above and give it another shot.";
+
+  banner.classList.add("visible");
+  banner.scrollIntoView({ behavior: "smooth", block: "center" });
+
+  document.getElementById("btn-submit").setAttribute("aria-disabled", "true");
+  document.getElementById("btn-submit").disabled = true;
+}
+
+function resetQuiz() {
+  QUESTIONS.forEach((q) => {
